const items = $input.all();
let certs = [];
if (items.length === 1 && Array.isArray(items[0].json)) {
  certs = items[0].json;
} else if (items.length === 1 && Array.isArray(items[0].json?.data)) {
  certs = items[0].json.data;
} else {
  certs = items.map(i => i.json);
}
const seen = new Set();
const out = [];
for (const cert of certs) {
  if (!cert || cert.id === undefined || cert.id === null) continue;
  const certId = String(cert.id);
  if (seen.has(certId)) continue;
  seen.add(certId);
  const event_id = 'src_crtsh_' + certId;
  const common_name = cert.common_name || cert.name_value || 'unknown';
  const issuer_name = cert.issuer_name || 'unknown';
  const headline = common_name + ' (issuer: ' + issuer_name + ')';
  const publisher = 'crt.sh';
  const product = 'ops';
  const tenant_id = 'shared';
  const workspace_id = 'shared';
  let captured_at = new Date().toISOString();
  if (cert.not_before) {
    const d = new Date(cert.not_before);
    captured_at = Number.isNaN(d.getTime()) ? String(cert.not_before) : d.toISOString();
  }
  const basin_event = {
    id: event_id,
    event_id: event_id,
    source_id: 'src_crtsh',
    publisher: publisher,
    headline: headline,
    product: product,
    tenant_id: tenant_id,
    workspace_id: workspace_id,
    captured_at: captured_at
  };
  out.push({
    json: {
      id: certId,
      event_id: event_id,
      artifact_path: 'crtsh/' + certId + '.json',
      raw_cert: cert,
      basin_event: basin_event
    }
  });
}
return out;

const res = $json.body || $json;
const committed = res?.result?.committed === 1 || res?.committed === 1 || res?.success === true;
if (!committed) {
  throw new Error('Basin ingest uncommitted: ' + JSON.stringify(res));
}
return {
  json: {
    committed: true,
    event_id: $('Normalize crt.sh Certs').item.json.event_id
  }
};

const input = $input.first()?.json || {};
const execution = input.execution || {};
const workflow = input.workflow || {};
return [{
  json: {
    workflowId: workflow.id || 'unknown',
    error: execution.error?.message || JSON.stringify(execution.error || 'Unknown error'),
    ts: new Date().toISOString()
  }
}];

